=== ValidateMergeRequest
package net.officefloor.hq.app.person;

import jakarta.validation.Valid;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Refuses (400) a merge that names no person to merge into. */
public class ValidateMergeRequest {
    public void validate(@RequestBody @Valid MergeRequest request, Out<MergeRequest> merge)
            throws InvalidPersonException {
        if (request.into() == null) {
            throw new InvalidPersonException("Choose the person to merge into.");
        }
        merge.set(request);
    }
}
=== CheckMerge
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Refuses (400) a merge unless a steward merges the person into another person on the sheet, neither of them
 * retired; publishes the merge.
 */
public class CheckMerge {
    public void check(@RequestParam("user") String user, @Val Person person, @Val MergeRequest request,
            SettingRepository settings, PersonRepository people, Out<Merge> merge) throws InvalidPersonException {
        if (settings.find(person.sheetId()).roleOf(user) != Role.STEWARD) {
            throw new InvalidPersonException("Only a steward may merge people.");
        }
        Person into = people.find(person.sheetId(), request.into());
        if (into == null) {
            throw new InvalidPersonException("No such person to merge into.");
        }
        if (into.id().equals(person.id())) {
            throw new InvalidPersonException("A person cannot be merged into themselves.");
        }
        if (person.retired() || into.retired()) {
            throw new InvalidPersonException("A retired person cannot be merged.");
        }
        merge.set(new Merge(person, into));
    }
}
=== MergePerson
package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.plugin.variable.Val;

/**
 * Merges the person into the other: their claims move to the other (numbers and dates kept), listed after the
 * other's in the order they were added, each keeping any figure a statement bound; then their name, aliases, patrons,
 * pool memberships and statements pass to the other (see {@link PersonRepository#merge}) and they leave the sheet.
 */
public class MergePerson {
    public void merge(@Val Merge merge, ClaimRepository claims, PersonRepository people) {
        List<Claim> moving = new ArrayList<>(claims.findForPerson(merge.from().sheetId(), merge.from().id()));
        Collections.reverse(moving);
        for (Claim claim : moving) {
            claims.moveMerged(claim, merge.into().id());
        }
        people.merge(merge.from(), merge.into());
    }
}
