271	     * Merge the person ({@code from}, their claims already moved) into the other: their name and then their aliases,
272	     * in the order added, become the other's newest aliases; their patrons are added after the other's, in the order named (not the other,
273	     * no repeats); anyone naming them as patron names the other instead (not themselves, no repeats); their pool
274	     * and crew memberships, crews they lead, and plans move to the other (shares added where the other is already a member), as do their shares of claims (dropped where the other holds one or owns the claim). Their statements join
275	     * the other's, before them: the other's count is both counts added, and the other's last statement stays theirs (or,
276	     * having none, becomes the merged person's). Their figures fixed for closed or soft-closed periods (due-total and
277	     * carried) are added to the other's for the same periods. Their grades,
278	     * holds, past retirements, watchers, snapshot lines and contact are dropped with them.
279	     */
280	    public void merge(Person from, Person into) {
281	        String sheetId = from.sheetId();
282	        long gone = from.id();
283	        long kept = into.id();
284	        List<String> aliases = jdbc.queryForList(
285	                "SELECT alias FROM person_alias WHERE sheet_id = ? AND person_id = ? ORDER BY id", String.class,
286	                sheetId, gone);
287	        jdbc.update("DELETE FROM person_alias WHERE sheet_id = ? AND person_id = ?", sheetId, gone);
288	        List<String> added = new ArrayList<>();
289	        added.add(from.name());
290	        added.addAll(aliases);
291	        for (String alias : added) {
292	            jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) VALUES (?, ?, ?)", sheetId, kept, alias);
293	        }
294	
295	        jdbc.update("INSERT INTO person_patron (sheet_id, person_id, patron_id) SELECT sheet_id, ?, patron_id"
296	                + " FROM person_patron p WHERE sheet_id = ? AND person_id = ? AND patron_id <> ? AND NOT EXISTS"
297	                + " (SELECT 1 FROM person_patron q WHERE q.person_id = ? AND q.patron_id = p.patron_id) ORDER BY seq",
298	                kept, sheetId, gone, kept, kept);
299	        jdbc.update("INSERT INTO person_patron (sheet_id, person_id, patron_id) SELECT sheet_id, person_id, ?"
300	                + " FROM person_patron p WHERE sheet_id = ? AND patron_id = ? AND person_id <> ? AND NOT EXISTS"
301	                + " (SELECT 1 FROM person_patron q WHERE q.person_id = p.person_id AND q.patron_id = ?) ORDER BY seq",
302	                kept, sheetId, gone, kept, kept);
303	        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND (person_id = ? OR patron_id = ?)", sheetId, gone,
304	                gone);
305	
306	        jdbc.update("UPDATE pool_member k SET share = share + (SELECT g.share FROM pool_member g WHERE"
307	                + " g.pool_id = k.pool_id AND g.person_id = ?) WHERE k.person_id = ? AND EXISTS (SELECT 1 FROM"
308	                + " pool_member g WHERE g.pool_id = k.pool_id AND g.person_id = ?)", gone, kept, gone);
309	        jdbc.update("DELETE FROM pool_member g WHERE g.person_id = ? AND EXISTS (SELECT 1 FROM pool_member k"
310	                + " WHERE k.pool_id = g.pool_id AND k.person_id = ?)", gone, kept);
311	        jdbc.update("UPDATE pool_member SET person_id = ? WHERE person_id = ?", kept, gone);
312	
313	        jdbc.update("DELETE FROM crew_member g WHERE g.sheet_id = ? AND g.person_id = ? AND (EXISTS (SELECT 1 FROM"
314	                + " crew_member k WHERE k.crew_id = g.crew_id AND k.person_id = ?) OR EXISTS (SELECT 1 FROM crew c"
315	                + " WHERE c.id = g.crew_id AND c.lead_id = ?))", sheetId, gone, kept, kept);
316	        jdbc.update("DELETE FROM crew_member m WHERE m.sheet_id = ? AND m.person_id = ? AND EXISTS (SELECT 1 FROM"
317	                + " crew c WHERE c.id = m.crew_id AND c.lead_id = ?)", sheetId, kept, gone);
318	        jdbc.update("UPDATE crew_member SET person_id = ? WHERE sheet_id = ? AND person_id = ?", kept, sheetId, gone);
319	        jdbc.update("UPDATE crew SET lead_id = ? WHERE sheet_id = ? AND lead_id = ?", kept, sheetId, gone);
320	
321	        jdbc.update("UPDATE person_plan SET person_id = ? WHERE sheet_id = ? AND person_id = ?", kept, sheetId, gone);
322	
323	        jdbc.update("DELETE FROM claim_share g WHERE g.sheet_id = ? AND g.person_id = ? AND (EXISTS (SELECT 1 FROM"
324	                + " claim_share k WHERE k.claim_id = g.claim_id AND k.person_id = ?) OR EXISTS (SELECT 1 FROM claim c"
325	                + " WHERE c.id = g.claim_id AND c.person_id = ?))", sheetId, gone, kept, kept);
326	        jdbc.update("UPDATE claim_share SET person_id = ? WHERE sheet_id = ? AND person_id = ?", kept, sheetId, gone);
327	
328	        jdbc.update("UPDATE period_person_total k SET total = total + (SELECT g.total FROM period_person_total g"
329	                + " WHERE g.sheet_id = k.sheet_id AND g.period_name = k.period_name AND g.person_id = ?), carried ="
330	                + " carried + (SELECT g.carried FROM period_person_total g WHERE g.sheet_id = k.sheet_id AND"
331	                + " g.period_name = k.period_name AND g.person_id = ?) WHERE k.sheet_id = ? AND k.person_id = ? AND"
332	                + " EXISTS (SELECT 1 FROM period_person_total g WHERE g.sheet_id = k.sheet_id AND g.period_name ="
333	                + " k.period_name AND g.person_id = ?)", gone, gone, sheetId, kept, gone);
334	        jdbc.update("DELETE FROM period_person_total g WHERE g.sheet_id = ? AND g.person_id = ? AND EXISTS (SELECT 1"
335	                + " FROM period_person_total k WHERE k.sheet_id = g.sheet_id AND k.period_name = g.period_name AND"
336	                + " k.person_id = ?)", sheetId, gone, kept);
337	        jdbc.update("UPDATE period_person_total SET person_id = ? WHERE sheet_id = ? AND person_id = ?", kept, sheetId,
338	                gone);
339	
340	        mergeStatements(sheetId, gone, kept);
341	        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ?", sheetId, gone);
342	        jdbc.update("DELETE FROM person_terms WHERE sheet_id = ? AND person_id = ?", sheetId, gone);
343	        jdbc.update("DELETE FROM person_hold WHERE sheet_id = ? AND person_id = ?", sheetId, gone);
344	        jdbc.update("DELETE FROM person_retirement WHERE sheet_id = ? AND person_id = ?", sheetId, gone);
345	        jdbc.update("DELETE FROM person_watch WHERE sheet_id = ? AND person_id = ?", sheetId, gone);
346	        jdbc.update("DELETE FROM person_snapshot WHERE sheet_id = ? AND person_id = ?", sheetId, gone);
347	        jdbc.update("DELETE FROM person WHERE sheet_id = ? AND id = ?", sheetId, gone);
348	    }
