350	    /**
351	     * Swap the person with the one above (up) or below (down) them in the sheet's list; their new position, counting
352	     * from 1, or 0 when there is no one there (the top person moving up, the bottom one down).
353	     */
354	    public int move(Person person, boolean up) {
355	        List<Map<String, Object>> order = jdbc.queryForList(
356	                "SELECT id, position FROM person WHERE sheet_id = ? ORDER BY position, id", person.sheetId());
357	        int at = -1;
358	        for (int i = 0; i < order.size(); i++) {
359	            if (((Number) order.get(i).get("id")).longValue() == person.id()) {
360	                at = i;
361	            }
362	        }
363	        int to = up ? at - 1 : at + 1;
364	        if (at < 0 || to < 0 || to >= order.size()) {
365	            return 0;
366	        }
367	        // the list renumbered 1..n with the two swapped, so no two people ever share a position
368	        for (int i = 0; i < order.size(); i++) {
369	            long position = i == at ? to + 1 : i == to ? at + 1 : i + 1;
370	            jdbc.update("UPDATE person SET position = ? WHERE id = ? AND sheet_id = ?", position,
371	                    order.get(i).get("id"), person.sheetId());
372	        }
373	        return to + 1;
374	    }
