473	    /**
474	     * Give the kept person the gone person's statements, before their own: the kept person's count becomes both
475	     * counts added, and their last statement stays theirs (or, having none, becomes the gone person's).
476	     */
477	    private void mergeStatements(String sheetId, long gone, long kept) {
478	        int goneCount = jdbc.queryForObject("SELECT statement_count FROM person WHERE sheet_id = ? AND id = ?",
479	                Integer.class, sheetId, gone);
480	        if (goneCount > 0) {
481	            // shifted through negatives so no two statements of the kept person share a seq on the way
482	            jdbc.update("UPDATE person_statement SET seq = -(seq + ?) WHERE sheet_id = ? AND person_id = ?", goneCount,
483	                    sheetId, kept);
484	            jdbc.update("UPDATE person_statement SET seq = -seq WHERE sheet_id = ? AND person_id = ?", sheetId, kept);
485	            jdbc.update("UPDATE person_statement SET person_id = ? WHERE sheet_id = ? AND person_id = ?", kept, sheetId,
486	                    gone);
487	            jdbc.update("UPDATE person k SET stated_total = (SELECT g.stated_total FROM person g WHERE g.id = ?),"
488	                    + " statement_date = (SELECT g.statement_date FROM person g WHERE g.id = ?)"
489	                    + " WHERE k.sheet_id = ? AND k.id = ? AND k.statement_count = 0", gone, gone, sheetId, kept);
490	            jdbc.update("UPDATE person SET statement_count = statement_count + ? WHERE sheet_id = ? AND id = ?",
491	                    goneCount, sheetId, kept);
492	        }
493	        jdbc.update("DELETE FROM person_statement WHERE sheet_id = ? AND person_id = ?", sheetId, gone);
494	    }
